import { ProjectDetail } from "march/landing"

// bilim şenliği: üç öğrenci projesi; sondaki "sonraki proje" kartı bir sonrakini açar, sonuncudan başa döner
// bir projenin biçimi (kapak ve galeri: görsel ya da düğüm)
type Picture = { src: string; alt: string; width: number; height: number }
type Project = { id: string; title: string; category?: string; year?: number | string; summary?: string; cover: Node | Picture }
type ProjectDetails = Project & { role?: string; client?: string; services?: string[]; body?: unknown; gallery?: (Node | Picture)[]; links?: { label: string; href: string }[] }
const Big = (p: { emoji: string }) => <div style={{ "font-size": "5rem", "text-align": "center", padding: "2rem" }} aria-hidden="true">{p.emoji}</div>

const RAW = [
  { id: "volkan", title: "Köpüren volkan", category: "Kimya", year: "5. sınıf", summary: "Sirke ve karbonatla patlayan bir dağ.", emoji: "🌋" },
  { id: "fasulye", title: "Işığa dönen fasulye", category: "Biyoloji", year: "4. sınıf", summary: "Bir kutuda labirent çözen filiz.", emoji: "🌱" },
  { id: "pil", title: "Limon pili", category: "Fizik", year: "6. sınıf", summary: "Dört limonla yanan bir LED.", emoji: "🍋" },
]
// her okumada yeni kapak düğümü
const project = (i: number): ProjectDetails => { const r = RAW[i]!; return { ...r, cover: <Big emoji={r.emoji} /> as Node } }

export function ScienceFair() {
  let $i = 0
  return <div>
    {() => {
      const i = $i
      return <ProjectDetail project={project(i)} reveal={false}
        next={{ project: project((i + 1) % RAW.length), onOpen: () => $i = (i + 1) % RAW.length }} />
    }}
  </div>
}

import { ProjectDetail } from "march/landing"
import { toast } from "march/ui"

// bir mimarlık ofisinin proje sayfası: künye, hizmetler, hikâye, büyütülebilen galeri ve basın bağlantısı
// bir projenin biçimi (kapak ve galeri: görsel ya da düğüm)
type Picture = { src: string; alt: string; width: number; height: number }
type Project = { id: string; title: string; category?: string; year?: number | string; summary?: string; cover: Node | Picture }
type ProjectDetails = Project & { role?: string; client?: string; services?: string[]; body?: unknown; gallery?: (Node | Picture)[]; links?: { label: string; href: string }[] }
const PROJECT: ProjectDetails = {
  id: "bag-evi", title: "Bağ Evi, Urla", category: "Konut", year: 2025,
  summary: "Zeytin ağaçlarının arasında, güneşi takip eden tek katlı bir ev.",
  role: "Mimari tasarım ve uygulama", client: "Özel müşteri", services: ["Mimari", "İç mekân", "Peyzaj"],
  cover: { src: "/media/dusk.jpg", alt: "Akşam ışığında ev", width: 1200, height: 800 },
  body: [
    <p>Arsadaki 40 yaşındaki zeytin ağaçlarının hiçbiri kesilmedi; ev, ağaçların arasındaki boşluğa yerleşti.</p>,
    <p>Geniş saçaklar yazın güneşi keser, kışın içeri alır. Yerel taş duvarlar evi serin tutar.</p>,
  ],
  gallery: [
    { src: "/media/dusk.jpg", alt: "Batıya bakan teras", width: 1200, height: 800 },
    { src: "/media/hadi-waves.jpg", alt: "Malzeme paleti", width: 960, height: 540 },
  ],
  links: [{ label: "Basında", href: "#basin" }],
}

export function ArchitectureCase() {
  return <ProjectDetail project={PROJECT} onBack={() => toast("Projeler listesine dönülüyor")}
    labels={{ back: "Tüm projeler", role: "Rol", client: "Müşteri", year: "Yıl", category: "Tür", services: "Hizmetler" }} />
}

import { ProjectDetail } from "march/landing"
import { Toggle, Card } from "march/ui"
import { chevronLeft, sparkles } from "march/icons"

// ProjectDetail'in bütün özellikleri bir arada: proje (başlık, kategori, yıl, özet, kapak, rol, müşteri, hizmetler,
// hikâye, galeri, bağlantılar), geri dönüş (onBack), sonraki proje (next), paylaşılan ad (shared), kategori satırı
// (eyebrow), künye (facts), geri ve sonraki ikonları, giriş hareketi (reveal), kendi metinler (labels) ve sınıf
// bir projenin biçimi (kapak ve galeri: görsel ya da düğüm)
type Picture = { src: string; alt: string; width: number; height: number }
type Project = { id: string; title: string; category?: string; year?: number | string; summary?: string; cover: Node | Picture }
type ProjectDetails = Project & { role?: string; client?: string; services?: string[]; body?: unknown; gallery?: (Node | Picture)[]; links?: { label: string; href: string }[] }
const Art = (p: { color: string; label: string }) =>
  <div style={{ background: p.color, color: "#fff", "aspect-ratio": "16 / 9", display: "grid", "place-items": "center", "font-size": "3rem" }} aria-hidden="true">{p.label}</div>

const LIST = [
  { id: "atlas", title: "Atlas Banka", color: "#7c5cff" },
  { id: "kite", title: "Kite uygulaması", color: "#2bb8ff" },
  { id: "lumen", title: "Lumen panosu", color: "#ff7a59" },
]
const project = (i: number): ProjectDetails => {
  const r = LIST[i % LIST.length]!
  return {
    id: r.id, title: r.title, category: "Marka", year: 2026, summary: "Kimlik, web sitesi ve hareket dili.",
    role: "Tasarım ve ön yüz", client: r.title, services: ["Kimlik", "Web", "Hareket"],
    cover: <Art color={r.color} label={r.title[0]!} /> as Node,
    body: <p>Bir haftalık keşifle başladık; tek bir hareket fikri bütün işi taşıdı.</p>,
    gallery: [<Art color="#3ecf8e" label="1" /> as Node, { src: "/media/hadi-waves.jpg", alt: "Dalgalar", width: 960, height: 540 }],
    links: [{ label: "Siteyi gör", href: "#site" }],
  }
}

export function ProjectDetailLab() {
  let $i = 0
  let $eyebrow = true
  let $facts = true
  let $motion = false
  let $backs = 0
  return <div sx={{ flex: "col", gap: 3 }}>
    <Card>
      <div sx={{ flex: ["row", "wrap"], gap: 3 }}>
        <Toggle label="Kategori satırı" bind:value={$eyebrow} />
        <Toggle label="Künye" bind:value={$facts} />
        <Toggle label="Giriş hareketi" bind:value={$motion} />
      </div>
      <p sx={{ color: "muted" }}>Geri basıldı: {$backs}</p>
    </Card>
    {() => {
      // sinyaller burada okunur: değişince sayfa yeniden çizilir
      const i = $i, eyebrow = $eyebrow, facts = $facts, motion = $motion
      return <ProjectDetail class="lab-detail" project={project(i)} shared={`lab-${i}`}
        onBack={() => $backs++} backIcon={chevronLeft} nextIcon={sparkles}
        next={{ project: project(i + 1) as Project, onOpen: () => $i = (i + 1) % LIST.length }}
        eyebrow={eyebrow} facts={facts} reveal={motion ? { effect: "blur", stagger: 60 } : false}
      labels={{ back: "Listeye dön", next: "Sıradaki iş", role: "Rol", client: "Müşteri", year: "Yıl", category: "Alan",
        services: "Hizmetler", openImage: (n: number) => `${n}. görseli büyüt` }} />
    }}
  </div>
}

import { test, expect, renderTest } from "march/testing"
import { ProjectDetailLab } from "./ProjectDetailLab.tsx"

// ProjectDetailLab'in testleri: kaydedince Testler sekmesinde çalışır
test("başlık h1, kapağın paylaşılan adı ve kendi metinler", () => {
  const s = renderTest(() => <ProjectDetailLab />)
  expect(s.get(".lab-detail h1")?.textContent).toContain("Atlas Banka")
  expect(s.get(".m-pd-cover")?.getAttribute("data-m-shared")).toBe("lab-0")
  expect(s.find("Müşteri")).not.toBe(null)
  expect(s.get('[aria-label="Hizmetler"]')).not.toBe(null)
  expect(s.find("2. görseli büyüt")).not.toBe(null)
})

test("geri düğmesi onBack'i çağırır", async () => {
  const s = renderTest(() => <ProjectDetailLab />)
  await s.click("Listeye dön")
  expect(s.find("Geri basıldı: 1")).not.toBe(null)
})

test("sonraki proje kartı bir sonrakini açar", async () => {
  const s = renderTest(() => <ProjectDetailLab />)
  expect(s.get(".m-pd-next")?.textContent).toContain("Sıradaki iş")
  await s.click(s.get(".m-pd-next")!)
  expect(s.get(".lab-detail h1")?.textContent).toContain("Kite uygulaması")
})

test("künye kapanınca rol satırı gider", async () => {
  const s = renderTest(() => <ProjectDetailLab />)
  expect(s.find("Rol")).not.toBe(null)
  await s.click("Künye")
  expect(s.find("Rol")).toBe(null)
})
